roundtrip.lowered_asl:
class.students.total = 200
class.students.blue = percent_of(class.students.total, 30)
class.students.not_blue = (class.students.total - class.students.blue)
class.students.red = percent_of(class.students.not_blue, 40)
class.students.yellow = (class.students.not_blue - class.students.red)
class.students.yellow_and_blue = (class.students.yellow + class.students.blue)
RETURN class.students.yellow_and_blue
